@pytest.mark.parametrize(
    "posted_on",
    [
        pytest.param("2026-02-28", id="before-today"),
        pytest.param("2026-03-01", id="on-today"),
    ],
)
def test_imports_record_posted_on_or_before_today(posted_on):
    record = {"account": "4010", "amount": "125.00", "posted_on": posted_on}

    entry = import_record(record, TODAY)

    assert entry.posted_on == date.fromisoformat(posted_on)
    assert entry.account == "4010"
    assert entry.amount == Decimal("125.00")
    assert entry.memo == ""


def test_rejects_future_posted_on():
    record = {"account": "4010", "amount": "125.00", "posted_on": "2026-03-02"}

    with pytest.raises(ImportRejected, match=r"^posted_on is in the future$"):
        import_record(record, TODAY)
